using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using CodexStrip;
class FocusStyleTest {
 [STAThread]static void Main(){var app=new Application();var w=new StripWindow(true){Width=320,Height=900};w.Loaded+=async delegate{try{foreach(var theme in new[]{"light","dark"}){w.SetTheme(theme);await Task.Delay(100);var b=(Button)typeof(StripWindow).GetField("dockButton",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);b.Focus();w.UpdateLayout();var frame=(Border)b.Template.FindName("frame",b);if(((SolidColorBrush)frame.BorderBrush).Color!=((SolidColorBrush)Design.B(Design.Canvas)).Color)throw new Exception("focused floating button has selected border");if(b.FocusVisualStyle==null)throw new Exception("keyboard focus visual missing");w.Snapshot("work/dock-focus-"+theme+".png");}File.WriteAllText("work/focus-style-test.txt","PASS: focused floating dock button has no active border in light/dark; keyboard focus visual retained");}catch(Exception e){File.WriteAllText("work/focus-style-test.txt",e.ToString());}finally{w.Close();}};app.Run(w);}
}
